import copy
import json
from pathlib import Path
import pickle
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, str(Path(sys.argv[1]).resolve()))
import click
from click._utils import Sentinel, UNSET, FLAG_NEEDS_VALUE


def require(condition, message):
    if not condition:
        raise AssertionError(message)


def roundtrip(value):
    return pickle.loads(pickle.dumps(value))


MODES = [('copy', copy.copy), ('deepcopy', copy.deepcopy), ('pickle', roundtrip)]


def parse(parameter, args=()):
    command = click.Command('review', params=[parameter])
    with command.make_context('review', list(args)) as context:
        return dict(context.params)


def same_parameter_fields(original, restored):
    require(restored is not original, 'parameter object was not copied')
    require(restored.name == original.name and restored.opts == original.opts, 'parameter name/declarations changed')
    require(restored._default_explicit == original._default_explicit, 'explicit default marker changed')
    if original.default is UNSET:
        require(restored.default is UNSET, 'raw missing default lost singleton identity')
    else:
        require(type(restored.default) is type(original.default) and restored.default == original.default, 'explicit default changed')
    if isinstance(original, click.Option):
        require(restored.secondary_opts == original.secondary_opts, 'secondary declarations changed')
        if original.flag_value is UNSET:
            require(restored.flag_value is UNSET, 'raw missing flag_value lost identity')
        else:
            require(restored.flag_value == original.flag_value, 'explicit flag value changed')


def sentinel_copy_identity():
    observed = []
    for member in Sentinel:
        for name, operation in MODES[:2]:
            restored = operation(member)
            require(restored is member, 'sentinel copy identity changed')
            observed.append([member.name, name, True])
    return observed


def sentinel_pickle_all_protocols():
    observed = []
    for member in Sentinel:
        for protocol in range(pickle.HIGHEST_PROTOCOL + 1):
            restored = pickle.loads(pickle.dumps(member, protocol=protocol))
            require(restored is member, 'sentinel pickle identity changed')
            require(restored.name == member.name and repr(restored) == repr(member), 'sentinel representation changed')
            observed.append([member.name, protocol, True])
    return observed


def shared_graph_and_dictionary_keys():
    graph = {UNSET: [UNSET, {'flag': FLAG_NEEDS_VALUE}], FLAG_NEEDS_VALUE: UNSET}
    observed = []
    for name, operation in MODES[1:]:
        restored = operation(graph)
        require(restored is not graph and set(restored) == {UNSET, FLAG_NEEDS_VALUE}, 'sentinel mapping keys changed')
        require(restored[UNSET][0] is UNSET and restored[UNSET][1]['flag'] is FLAG_NEEDS_VALUE, 'nested sentinel identity changed')
        require(restored[FLAG_NEEDS_VALUE] is UNSET, 'shared sentinel graph changed')
        observed.append([name, True])
    return observed


def unset_option_defaults_and_names():
    observed = []
    for kwargs, expected in [({}, None), ({'is_flag': True}, False), ({'is_flag': True, 'multiple': True}, ())]:
        original = click.Option(['-v', '--example-value', 'value'], **kwargs)
        require(original.default is UNSET and original.flag_value is UNSET, 'unexpected source raw-default contract')
        require(parse(original) == {'value': expected}, 'unexpected source effective default')
        for name, operation in MODES:
            restored = operation(original)
            same_parameter_fields(original, restored)
            require(restored.name == 'value' and restored.opts == ['-v', '--example-value'], 'explicit option name changed')
            require(parse(restored) == {'value': expected}, 'restored option effective default changed')
            require(restored.to_info_dict()['default'] == expected, 'introspection default changed')
            observed.append({'mode': name, 'kwargs': kwargs, 'value': expected})
    return observed


def argument_defaults_and_names():
    observed = []
    for kwargs, expected in [({'required': False}, None), ({'required': False, 'default': 0, 'type': int}, 0)]:
        original = click.Argument(['example-value'], **kwargs)
        require(original.name == 'example_value', 'unexpected source argument normalization')
        for name, operation in MODES:
            restored = operation(original)
            same_parameter_fields(original, restored)
            require(parse(restored) == {'example_value': expected}, 'restored argument default changed')
            observed.append({'mode': name, 'expected': expected, 'name': restored.name})
    return observed


def copy_ownership_semantics():
    observed = []
    for name, operation in MODES:
        original = click.Option(['--value'], multiple=True, type=int, default=[1, 2])
        restored = operation(original)
        same_parameter_fields(original, restored)
        if name == 'copy':
            require(restored.opts is original.opts and restored.default is original.default, 'ordinary shallow copy semantics changed')
            ownership = 'shallow aliases retained'
        else:
            require(restored.opts is not original.opts and restored.default is not original.default, 'deep/serialized ownership was not independent')
            restored.opts.append('--other')
            restored.default.append(3)
            require(original.opts == ['--value'] and original.default == [1, 2], 'restored mutation leaked to original')
            ownership = 'independent nested lists'
        observed.append({'mode': name, 'ownership': ownership, 'name': restored.name})
    return observed


def missing_and_invalid_value_errors():
    observed = []
    for name, operation in MODES:
        required = operation(click.Option(['--value'], required=True))
        caught = None
        try:
            parse(required)
        except BaseException as error:
            caught = error
        require(isinstance(caught, click.MissingParameter) and caught.param.name == 'value', 'required parameter failure changed')
        integer = operation(click.Option(['--value'], type=int))
        caught = None
        try:
            parse(integer, ['--value', 'bad-int'])
        except BaseException as error:
            caught = error
        require(isinstance(caught, click.BadParameter) and caught.param.name == 'value', 'invalid typed value failure changed')
        observed.append({'mode': name, 'missing': 'MissingParameter', 'invalid_value': 'BadParameter'})
    return observed


def explicit_falsy_and_derived_defaults():
    observed = []
    for kwargs, expected in [({'default': None}, None), ({'default': 0}, 0), ({'default': False}, False),
                             ({'default': ''}, ''), ({'flag_value': 'fast', 'default': True}, 'fast'),
                             ({'count': True}, 0)]:
        original = click.Option(['--value'], **kwargs)
        require(parse(original) == {'value': expected}, 'unexpected source explicit/derived default')
        for name, operation in MODES:
            restored = operation(original)
            same_parameter_fields(original, restored)
            require(parse(restored) == {'value': expected}, 'restored explicit/derived default changed')
            observed.append({'mode': name, 'kwargs': kwargs, 'value': expected,
                             'default_explicit': restored._default_explicit})
    return observed


results = {}
for function in [sentinel_copy_identity, sentinel_pickle_all_protocols, shared_graph_and_dictionary_keys,
                 unset_option_defaults_and_names, argument_defaults_and_names, copy_ownership_semantics,
                 missing_and_invalid_value_errors, explicit_falsy_and_derived_defaults]:
    try:
        results[function.__name__] = {'passed': True, 'observed': function()}
    except BaseException as error:
        results[function.__name__] = {'passed': False, 'exception': type(error).__name__, 'message': str(error)}
print(json.dumps({'module_file': str(Path(click.__file__).resolve()),
                  'python_version': sys.version, 'highest_pickle_protocol': pickle.HIGHEST_PROTOCOL,
                  'passed': sum(result['passed'] for result in results.values()),
                  'total': len(results), 'results': results}))
